for _ in range(m):
 a,b=map(int,input().split());g[a].append(b);g[b].append(a)
s,t=map(int,input().split());d=[-1]*(n+1);d[s]=0;q=deque([s])
while q:
 v=q.popleft()
 for u in g[v]:
  if d[u]<0: d[u]=d[v]+1;q.append(u)
print(d[t])

