from math import hypot
n=int(input())
e=float(input())
p=[tuple(map(float,input().split())) for _ in range(n)]
left=set(range(n));cs=[]
while left:
    seed=left.pop();q=[seed];c=[seed]
    for i in q:
        for j in list(left):
            if hypot(p[i][0]-p[j][0],p[i][1]-p[j][1])<e:
                left.remove(j);q.append(j);c.append(j)
    if len(c)>=3: cs.append(c)
centers=[]
for c in cs:
    centers.append(min(c,key=lambda i:sum(hypot(p[i][0]-p[j][0],p[i][1]-p[j][1]) for j in c)))
print(int(sum(p[i][0] for i in centers)/len(centers)*10000),int(sum(p[i][1] for i in centers)/len(centers)*10000))

