from functools import cache
@cache
def game(s):
    if s >= 51:
        return 0
    moves = [game(nxt) for nxt in (s + 1, s + 3, s * 3) if nxt % 2 == 1]
    if 0 in moves:
        return 1
    if min(moves) < 0:
        return -max(x for x in moves if x < 0) + 1
    return -max(moves)
print(next(s for s in range(1, 51) if any(game(nxt) == 1 for nxt in (s + 1, s + 3, s * 3) if nxt % 2)))

