from math import ceil
@cache
def game(a, b):
    if a + b <= 32:
        return 0
    moves = []
    if a > 0: moves.append(game(a - 1, b))
    if a > 1: moves.append(game(ceil(a / 2), b))
    if b > 0: moves.append(game(a, b - 1))
    if b > 1: moves.append(game(a, ceil(b / 2)))
    if 0 in moves:
        return 1
    if min(moves) < 0:
        return -max(x for x in moves if x < 0) + 1
    return -max(moves)
