def game(s):
    if s >= 1000:
        return 0
    moves = [game(s + 100), game(s * 2)]
    if 0 in moves:
        return 1
    if min(moves) < 0:
        return -max(x for x in moves if x < 0) + 1
    return -max(moves)
print(len([s for s in range(1, 1000) if game(s) == -1]))

